document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("button-generator");let e=document.getElementById("color-box"),o=document.getElementById("color-code");t.addEventListener("click",function(){var t="#"+Math.floor(16777215*Math.random()).toString(16).padStart(6,"0");e.style.backgroundColor=t,o.textContent=t.toUpperCase()})});